    public static void main(Args    _args)
    {
        #OCCRetryCount

        METransferOrderExtractScreenUpdateStatus        extractScreenDialog;
        FormRun                                         formRun = _args.caller();
        FormDataSource                                  metInventTransferTableExtDS     = formRun.dataSource(formDataSourceStr(METTransferOrderExtractScreen, METInventTransferTableExt));
        FormDataSource                                  inventTransferTableDS           = formRun.dataSource(formDataSourceStr(METTransferOrderExtractScreen, InventTransferTable));

        MultiSelectionHelper                            helper;
        METInventTransferTableExt                       metInventTransferTableExt;
        
        str                                             boxText,fromStatus,toStatus;

        helper                      = MultiSelectionHelper::construct();
        helper.parmDataSource(metInventTransferTableExtDS);         
        metInventTransferTableExt = helper.getfirst(); 

        fromStatus          = enum2Str(metInventTransferTableExt.OrderExtractStatus);
        toStatus            = enum2Str(METOrderExtractStatus::Open) == fromStatus ? enum2Str(METOrderExtractStatus::ReadyForExtract) : enum2Str(METOrderExtractStatus::Open);
        boxText             = strFmt("@MET:UpdateStatusText",fromStatus,toStatus);

        try
        {
            ttsbegin;
            if(Box::yesNo(boxText,DialogButton::Yes) == DialogButton::Yes)
            {
                if(metInventTransferTableExt.OrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
                {
                    while(metInventTransferTableExt)
                    {
                        metInventTransferTableExt.selectForUpdate(true);

                        metInventTransferTableExt.OrderExtractStatus    = METOrderExtractStatus::Open;
                        metInventTransferTableExt.update();

                        metInventTransferTableExt = helper.getNext();
                    }
                }

                if(metInventTransferTableExt.OrderExtractStatus == METOrderExtractStatus::Open)
                {
                    while(metInventTransferTableExt)
                    {
                        METransferOrderExtractScreenUpdateStatus::updateStatus(metInventTransferTableExt);
                        metInventTransferTableExt = helper.getNext();
                    }
                }
            }
            ttscommit;
        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

public static METransferOrderExtractScreenUpdateStatus construct()
{
    return new METransferOrderExtractScreenUpdateStatus();
}
